---@module 'hl'

-- =========================
-- WIN95 WINDOW FRAMES (C1): hyprbars title bars + imgborders bevel
-- =========================
-- WRITTEN, NEVER RUN LIVE. Both plugins are installed by hand (see docs/theming.md) and every call here is
-- guarded: a plugin that isn't loaded is skipped, a Lua error is caught by the pcall in hyprland.lua, so a
-- missing plugin or a wrong option name can't break the rest of the config. Option names below come from the
-- plugins' READMEs and are UNVERIFIED against 0.56 (marked "guess").
--
-- Colours come from theme_colors.lua (generated by quickshell/theme/apply.py). The bevel image
-- ~/.config/hypr/win95-border.png is generated by apply.py too (a 7x7 nine-slice, 3 px frame).

local okc, c = pcall(require, "theme_colors")
if not okc or type(c) ~= "table" then
    c = {}
end
-- cherry fallbacks, like look_and_feel.lua
local bar_active = c.bar_active or "rgb(c950bb)"
local bar_active_text = c.bar_active_text or "rgb(20091d)"
local bar_inactive = c.bar_inactive or "rgb(c7a4cc)"
local bar_inactive_text = c.bar_inactive_text or "rgb(321d32)"

local function loaded(name)
    for _, p in ipairs(hl.get_loaded_plugins()) do
        if p.name == name then
            return true
        end
    end
    return false
end

local buttons_added = false

local function configure()
    if loaded("hyprbars") then
        -- 20 px Win95 bar: left-aligned title in Charcoal, buttons on the right; grey (muted) until focused
        hl.config({
            plugin = {
                hyprbars = {
                    bar_height = 20,
                    bar_color = bar_inactive,
                    col = { text = bar_inactive_text },
                    bar_title_enabled = true,
                    bar_text_font = "Charcoal",
                    bar_text_size = 12,
                    bar_text_align = "left",
                    bar_buttons_alignment = "right",
                    bar_padding = 4,
                    bar_button_padding = 2,
                    bar_precedence_over_border = true,
                }
            }
        })
        -- maximise and close (Hyprland has no minimise); added once, configure() also runs on every reload.
        -- Guess: add_button takes bg_color / fg_color / size / icon / action, as in the README's Lua example.
        if not buttons_added and hl.plugin.hyprbars and hl.plugin.hyprbars.add_button then
            buttons_added = true
            hl.plugin.hyprbars.add_button({
                bg_color = bar_inactive, fg_color = bar_inactive_text, size = 16, icon = "[]",
                action = "hyprctl dispatch 'hl.dsp.window.fullscreen({ mode = \"maximized\", action = \"toggle\" })'",
            })
            hl.plugin.hyprbars.add_button({
                bg_color = bar_inactive, fg_color = bar_inactive_text, size = 16, icon = "x",
                action = "hyprctl dispatch 'hl.dsp.window.close()'",
            })
        end
    end

    if loaded("imgborders") then
        -- the 3 px Win95 bevel around every window (guess: sizes / insets are top,right,bottom,left; 0 inset)
        hl.config({
            plugin = {
                imgborders = {
                    enabled = true,
                    image = os.getenv("HOME") .. "/.config/hypr/win95-border.png",
                    sizes = "3,3,3,3",
                    insets = "0,0,0,0",
                    scale = 1,
                    smooth = false,
                    blur = false,
                }
            }
        })
    end
end

-- Title bars on FLOATING windows only (tiled windows keep their full height), accent while focused.
-- Guess: plugin window-rule properties are written as the "hyprbars:<name>" strings.
local function rules()
    if not loaded("hyprbars") then
        return
    end
    hl.window_rule({ name = "hyprbars-no-bar-tiled", match = { float = false }, ["hyprbars:no_bar"] = true })
    hl.window_rule({
        name = "hyprbars-focused",
        match = { float = true, focus = true },
        ["hyprbars:bar_color"] = bar_active,
        ["hyprbars:title_color"] = bar_active_text,
    })
end

local function apply()
    configure()
    rules()
end

hl.on("hyprland.start", apply)
hl.on("config.reloaded", apply)
